package com.example.safesteps;import android.content.Context;import android.graphics.*;import android.view.*;import java.util.*;
public class PatternLockView extends View{Paint p=new Paint(1);Paint l=new Paint(1);List<Integer> pts=new ArrayList<>();float[]x=new float[9],y=new float[9];float r,cx,cy;boolean draw;public PatternLockView(Context c){super(c);init();}void init(){p.setColor(Color.rgb(205,218,232));l.setColor(Color.rgb(55,145,235));l.setStyle(Paint.Style.STROKE);l.setStrokeWidth(9);l.setStrokeCap(Paint.Cap.ROUND);setBackgroundColor(Color.WHITE);}protected void onDraw(Canvas c){float s=Math.min(getWidth(),getHeight()),cell=s/3f;r=cell*.15f;float ox=(getWidth()-s)/2,oy=(getHeight()-s)/2;for(int i=0;i<9;i++){int row=i/3,col=i%3;x[i]=ox+col*cell+cell/2;y[i]=oy+row*cell+cell/2;}if(!pts.isEmpty()){Path q=new Path();q.moveTo(x[pts.get(0)],y[pts.get(0)]);for(int i=1;i<pts.size();i++)q.lineTo(x[pts.get(i)],y[pts.get(i)]);if(draw)q.lineTo(cx,cy);c.drawPath(q,l);}for(int i=0;i<9;i++){p.setColor(pts.contains(i)?Color.rgb(55,145,235):Color.rgb(205,218,232));c.drawCircle(x[i],y[i],pts.contains(i)?r*1.45f:r,p);}}public boolean onTouchEvent(MotionEvent e){if(e.getAction()==0){pts.clear();draw=true;cx=e.getX();cy=e.getY();add(cx,cy);invalidate();return true;}if(e.getAction()==2){cx=e.getX();cy=e.getY();add(cx,cy);invalidate();return true;}if(e.getAction()==1){draw=false;add(e.getX(),e.getY());invalidate();return true;}return true;}void add(float a,float b){for(int i=0;i<9;i++){float dx=a-x[i],dy=b-y[i];if(Math.hypot(dx,dy)<=r*2.5&&!pts.contains(i)){pts.add(i);return;}}}public String getPattern(){StringBuilder b=new StringBuilder();for(int i:pts)b.append(i+1);return b.toString();}}
